begin;
create extension if not exists pgtap with schema extensions;
create extension if not exists dblink with schema extensions;
select no_plan();
insert into auth.users(id) values('d1100000-0000-0000-0000-000000000001');
insert into public.profiles(id,full_name,username,role,is_active) values('d1100000-0000-0000-0000-000000000001','D1 Race Admin','d1-race-admin','admin',true);
insert into public.vehicles(id,registration,make,model,vehicle_type,status) values('d4100000-0000-0000-0000-000000000001','D1-RACE','D','Race','Truck','available');
insert into public.documents(id,vehicle_id,uploader_profile_id,document_type,file_path,file_name,valid_until) values('d6100000-0000-0000-0000-000000000001','d4100000-0000-0000-0000-000000000001','d1100000-0000-0000-0000-000000000001','insurance','vehicle/race/doc/insurance.pdf','insurance.pdf',current_date+30);
commit;
begin;
select extensions.dblink_connect('d1_a','host=host.docker.internal port=54322 dbname=postgres user=postgres password=postgres');select extensions.dblink_connect('d1_b','host=host.docker.internal port=54322 dbname=postgres user=postgres password=postgres');
select extensions.dblink_exec('d1_a','begin;set local role service_role;set local lock_timeout=''5s'';set local statement_timeout=''10s''');
select extensions.dblink_exec('d1_b','begin;set local role service_role;set local lock_timeout=''5s'';set local statement_timeout=''10s''');
select ok(extensions.dblink_send_query('d1_a',$$select * from public.reconcile_document_expiry_alerts('d6100000-0000-0000-0000-000000000001',null)$$)=1,'First reconciliation starts');
select pg_sleep(.1);
select ok(extensions.dblink_send_query('d1_b',$$select * from public.reconcile_document_expiry_alerts('d6100000-0000-0000-0000-000000000001',null)$$)=1,'Concurrent reconciliation starts');
select * from extensions.dblink_get_result('d1_a',false) as r(created_count int,resolved_count int,updated_count int);select * from extensions.dblink_get_result('d1_a',false) as r(created_count int,resolved_count int,updated_count int);select extensions.dblink_exec('d1_a','commit');
select * from extensions.dblink_get_result('d1_b',false) as r(created_count int,resolved_count int,updated_count int);select * from extensions.dblink_get_result('d1_b',false) as r(created_count int,resolved_count int,updated_count int);select extensions.dblink_exec('d1_b','commit');
select is((select count(*) from public.alerts where document_id='d6100000-0000-0000-0000-000000000001' and alert_state='active'),1::bigint,'Concurrent reconciliation leaves one active alert');
select is((select count(*) from public.activity_logs where document_id='d6100000-0000-0000-0000-000000000001' and action_type='alert_created'),1::bigint,'Concurrent reconciliation leaves one creation activity');
select is((select count(*) from public.notifications where document_id='d6100000-0000-0000-0000-000000000001'),1::bigint,'Concurrent reconciliation deduplicates recipient notification');
select extensions.dblink_disconnect('d1_a');select extensions.dblink_disconnect('d1_b');
select * from finish();
delete from public.notifications where document_id='d6100000-0000-0000-0000-000000000001';delete from public.activity_logs where document_id='d6100000-0000-0000-0000-000000000001';delete from public.alerts where document_id='d6100000-0000-0000-0000-000000000001';delete from public.documents where id='d6100000-0000-0000-0000-000000000001';delete from public.vehicles where id='d4100000-0000-0000-0000-000000000001';delete from public.profiles where id='d1100000-0000-0000-0000-000000000001';delete from auth.users where id='d1100000-0000-0000-0000-000000000001';
commit;
